import pathlib, subprocess
base=pathlib.Path('/workspace/repo-vul/src-vul/espeak-ng')
out=subprocess.run(['grep','-RIn','int LookupMnem\|LookupMnem(',str(base/'src/libespeak-ng')],text=True,stdout=subprocess.PIPE).stdout
print('\n'.join(out.splitlines()[:80]))
for rel in ['src/libespeak-ng/mnemonics.c','src/libespeak-ng/speech.c','src/libespeak-ng/encoding.c','src/libespeak-ng/readclause.c']:
    p=base/rel
    if p.exists():
        lines=p.read_text(errors='ignore').splitlines()
        print('\n====',rel,'====')
        for i,l in enumerate(lines[:120],1): print(f'{i:5d} {l}')
